import{db}from"@/lib/db";import{nextPublicationSlot}from"@/lib/publication/schedule";
export async function scheduleArtwork(artworkId:string,now=new Date()){const existing=await db.publicationQueueItem.findMany({where:{status:"PENDING",scheduledFor:{gte:now}},select:{scheduledFor:true}});const slot=nextPublicationSlot(now,existing.map(x=>x.scheduledFor),6);return db.$transaction([db.artwork.update({where:{id:artworkId},data:{status:"SCHEDULED",approvedAt:now}}),db.publicationQueueItem.upsert({where:{artworkId},create:{artworkId,scheduledFor:slot},update:{scheduledFor:slot,status:"PENDING"}})])}
export async function publishImmediately(artworkId:string,now=new Date()){return db.$transaction(async tx=>{const artwork=await tx.artwork.update({where:{id:artworkId},data:{status:"PUBLISHED",approvedAt:now,publishedAt:now}});await tx.publicationQueueItem.updateMany({where:{artworkId,status:{in:["PENDING","PROCESSING"]}},data:{status:"CANCELLED"}});return artwork})}
export async function publishDue(now=new Date()){const due=await db.publicationQueueItem.findMany({where:{status:"PENDING",scheduledFor:{lte:now}},select:{id:true,artworkId:true}});let published=0;for(const item of due){await db.$transaction(async tx=>{const lock=await tx.publicationQueueItem.updateMany({where:{id:item.id,status:"PENDING"},data:{status:"PROCESSING",lockedAt:now,attempts:{increment:1}}});if(!lock.count)return;await tx.artwork.update({where:{id:item.artworkId},data:{status:"PUBLISHED",publishedAt:now}});await tx.publicationQueueItem.update({where:{id:item.id},data:{status:"PUBLISHED",publishedAt:now}});published++})}return published}