import{db}from"@/lib/db";import{publishImmediately}from"./publication-service";
export async function moderate(id:string,moderatorId:string,decision:"approve"|"reject"|"hide"|"restore",reason?:string){const a=await db.artwork.findUniqueOrThrow({where:{id}});if(decision==="approve"){if(a.status!=="PENDING")throw new Error("Работа не ожидает модерации");await db.moderationAction.create({data:{artworkId:id,moderatorId,action:"APPROVE",fromStatus:a.status,toStatus:"PUBLISHED",reason}});return publishImmediately(id)}const map={reject:{from:["PENDING"],to:"REJECTED",action:"REJECT"},hide:{from:["PUBLISHED","SCHEDULED"],to:"HIDDEN",action:"HIDE"},restore:{from:["HIDDEN"],to:"PUBLISHED",action:"RESTORE"}} as const;const x=map[decision];if(!(x.from as readonly string[]).includes(a.status))throw new Error("Недопустимое решение");return db.$transaction([db.artwork.update({where:{id},data:{status:x.to,moderationNote:reason,hiddenAt:decision==="hide"?new Date():null}}),db.moderationAction.create({data:{artworkId:id,moderatorId,action:x.action,fromStatus:a.status,toStatus:x.to,reason}})])}