"use server";
import bcrypt from"bcryptjs";import{headers}from"next/headers";import{redirect}from"next/navigation";import{revalidatePath}from"next/cache";import{signIn,signOut}from"@/auth";import{db}from"@/lib/db";import{registerSchema}from"@/lib/validation/auth";import{changeEmailSchema,changePasswordSchema}from"@/lib/validation/account";import{enforceRateLimit}from"@/lib/rate-limit";import{requireAdmin,requireUser}from"@/lib/auth/guards";import{createArtwork,deleteArtwork,submitArtwork,updateArtwork}from"@/lib/services/artwork-service";import{moderate}from"@/lib/services/moderation-service";import{prepareAvatar}from"@/lib/storage/avatar";import{deleteStored,writeStored}from"@/lib/storage/local-storage";import{categorySchema,slugifyCategory}from"@/lib/validation/category";import{commentSchema}from"@/lib/social";import{createStory}from"@/lib/services/story-service";
const val=(f:FormData,k:string)=>String(f.get(k)||"");async function ip(){return(await headers()).get("x-forwarded-for")||"local"}
export async function registerAction(f:FormData){await enforceRateLimit("REGISTER",await ip(),5,3600000);const started=Number(val(f,"startedAt"));if(!started||Date.now()-started<1200)throw new Error("Форма отправлена слишком быстро");const p=registerSchema.parse({email:val(f,"email"),password:val(f,"password"),displayName:val(f,"displayName"),website:val(f,"website")});await db.user.create({data:{email:p.email,passwordHash:await bcrypt.hash(p.password,12),displayName:p.displayName}});await signIn("credentials",{email:p.email,password:p.password,redirectTo:"/dashboard"})}
export async function loginAction(f:FormData){await enforceRateLimit("LOGIN",await ip(),10,900000);await signIn("credentials",{email:val(f,"email"),password:val(f,"password"),redirectTo:"/dashboard"})}
export async function logoutAction(){await signOut({redirectTo:"/"})}
export async function createStoryAction(f:FormData){const u=await requireUser();await enforceRateLimit("STORY",u.id,5,3600000);const files=f.getAll("illustrations").filter((x):x is File=>x instanceof File&&x.size>0);await createStory({authorId:u.id,title:val(f,"title"),body:val(f,"body"),description:val(f,"description"),sourceLocale:val(f,"sourceLocale")||"ru",illustrations:files});revalidatePath("/dashboard");revalidatePath("/stories")}
export async function storyAction(f:FormData){const u=await requireUser();const id=val(f,"id"),op=val(f,"op");const story=await db.story.findUniqueOrThrow({where:{id}});if(story.authorId!==u.id&&!["ADMIN","MODERATOR"].includes(u.role))throw new Error("Нет доступа к рассказу");if(op==="publish"){if(story.status!=="DRAFT")throw new Error("Рассказ уже отправлен или опубликован");await db.story.update({where:{id},data:{status:"PUBLISHED",publishedAt:new Date(),approvedAt:new Date()}})}else if(op==="delete"){if(story.status!=="DRAFT")throw new Error("Удалять можно только черновик");await db.story.update({where:{id},data:{status:"DELETED",deletedAt:new Date()}})}revalidatePath("/dashboard");revalidatePath("/stories")}
export async function uploadAction(f:FormData){const u=await requireUser();await enforceRateLimit("UPLOAD",u.id,10,3600000);await createArtwork(u.id,{title:val(f,"title"),description:val(f,"description"),sourceLocale:val(f,"sourceLocale"),categoryId:val(f,"categoryId"),tags:val(f,"tags"),file:f.get("file") as File,adults:f.get("adults")==="on",consensual:f.get("consensual")==="on",noDeepfake:f.get("noDeepfake")==="on"});redirect("/dashboard")}
export async function artworkAction(f:FormData){const u=await requireUser(),id=val(f,"id"),op=val(f,"op");if(op==="submit")await submitArtwork(u.id,id);else if(op==="delete")await deleteArtwork(u.id,id);else await updateArtwork(u.id,id,{title:val(f,"title"),description:val(f,"description"),sourceLocale:val(f,"sourceLocale"),categoryId:val(f,"categoryId")||null});revalidatePath("/dashboard")}
export async function moderationAction(f:FormData){const u=await requireAdmin();await moderate(val(f,"id"),u.id,val(f,"decision") as "approve"|"reject"|"hide"|"restore",val(f,"reason"));revalidatePath("/admin")}
export async function changeEmailAction(f:FormData){const u=await requireUser();await enforceRateLimit("ACCOUNT_EMAIL",u.id,5,3600000);const p=changeEmailSchema.parse({email:val(f,"email"),currentPassword:val(f,"currentPassword")});const current=await db.user.findUniqueOrThrow({where:{id:u.id}});if(!await bcrypt.compare(p.currentPassword,current.passwordHash))throw new Error("Неверный текущий пароль");const duplicate=await db.user.findFirst({where:{email:p.email,id:{not:u.id}}});if(duplicate)throw new Error("Этот email уже используется");await db.user.update({where:{id:u.id},data:{email:p.email}});await signOut({redirectTo:"/login?account=email-changed"})}
export async function changePasswordAction(f:FormData){const u=await requireUser();await enforceRateLimit("ACCOUNT_PASSWORD",u.id,5,3600000);const p=changePasswordSchema.parse({currentPassword:val(f,"currentPassword"),newPassword:val(f,"newPassword"),confirmPassword:val(f,"confirmPassword")});const current=await db.user.findUniqueOrThrow({where:{id:u.id}});if(!await bcrypt.compare(p.currentPassword,current.passwordHash))throw new Error("Неверный текущий пароль");if(await bcrypt.compare(p.newPassword,current.passwordHash))throw new Error("Новый пароль должен отличаться от текущего");await db.user.update({where:{id:u.id},data:{passwordHash:await bcrypt.hash(p.newPassword,12)}});await signOut({redirectTo:"/login?account=password-changed"})}
export async function avatarAction(f:FormData){const u=await requireUser();await enforceRateLimit("AVATAR",u.id,10,3600000);const current=await db.userAvatar.findUnique({where:{userId:u.id}});if(val(f,"op")==="delete"){if(current){await db.userAvatar.delete({where:{userId:u.id}});await deleteStored(current.storageKey)}revalidatePath("/dashboard/settings");return}const file=f.get("avatar");if(!(file instanceof File)||file.size===0)throw new Error("Выберите изображение");const avatar=await prepareAvatar(Buffer.from(await file.arrayBuffer()));const key=`avatars/${u.id}.webp`;await writeStored(key,avatar.data);await db.userAvatar.upsert({where:{userId:u.id},create:{userId:u.id,storageKey:key,mimeType:avatar.mimeType},update:{storageKey:key,mimeType:avatar.mimeType}});revalidatePath("/dashboard/settings")}
export async function createCategoryAction(f:FormData){await requireAdmin();const p=categorySchema.parse({name:val(f,"name"),description:val(f,"description")});const base=slugifyCategory(p.name);if(!base)throw new Error("Название должно содержать латинские буквы или цифры");let slug=base,index=2;while(await db.category.findUnique({where:{slug}}))slug=`${base}-${index++}`;await db.category.create({data:{name:p.name,slug,description:p.description||null}});revalidatePath("/admin");revalidatePath("/categories");revalidatePath("/dashboard/uploads/new")}
export async function toggleLikeAction(f:FormData){const u=await requireUser(),artworkId=val(f,"artworkId"),slug=val(f,"slug");await enforceRateLimit("LIKE",u.id,60,60000);const where={artworkId_userId:{artworkId,userId:u.id}};const existing=await db.artworkLike.findUnique({where});if(existing)await db.artworkLike.delete({where});else await db.artworkLike.create({data:{artworkId,userId:u.id}});revalidatePath(`/artwork/${slug}`)}
export async function createCommentAction(f:FormData){const u=await requireUser(),artworkId=val(f,"artworkId"),slug=val(f,"slug");await enforceRateLimit("COMMENT",u.id,12,3600000);const p=commentSchema.parse({content:val(f,"content")});const art=await db.artwork.findFirst({where:{id:artworkId,status:"PUBLISHED",deletedAt:null},select:{id:true}});if(!art)throw new Error("Работа не найдена");await db.comment.create({data:{artworkId,authorId:u.id,content:p.content}});revalidatePath(`/artwork/${slug}`)}
